///! Linux errno values and a zig error set for all known errors.
///! Unless you're a compiler developer, you're probably looking for std.os.linux.E or std.os.linux.ErrnoError.
const builtin = @import("builtin");
const native_arch = builtin.cpu.arch;

pub const NUM_ERRNO_CODES = 4096;

pub const TargetErrno = switch (native_arch) {
    .mips, .mipsel, .mips64, .mips64el => Mips,
    .sparc, .sparc64 => Sparc,
    else => Generic,
};

