/// Map of errno value to error on the target architecture.
pub const targetErrnoMap = switch (native_arch) {
    .mips, .mipsel, .mips64, .mips64el => mipsErrnoMap(),
    .sparc, .sparc64 => sparcErrnoMap(),
    else => genericErrnoMap(),
};

