            .NSRBADNAME => map[@intFromEnum(e)] = error.ENSRBADNAME,
            .NSRBADFAMILY => map[@intFromEnum(e)] = error.ENSRBADFAMILY,
            .NSRBADRESP => map[@intFromEnum(e)] = error.ENSRBADRESP,
            .NSRCONNREFUSED => map[@intFromEnum(e)] = error.ENSRCONNREFUSED,
            .NSRTIMEOUT => map[@intFromEnum(e)] = error.ENSRTIMEOUT,
            .NSROF => map[@intFromEnum(e)] = error.ENSROF,
            .NSRFILE => map[@intFromEnum(e)] = error.ENSRFILE,
            .NSRNOMEM => map[@intFromEnum(e)] = error.ENSRNOMEM,
            .NSRDESTRUCTION => map[@intFromEnum(e)] = error.ENSRDESTRUCTION,
